window.SEARCH_INDEX = [{"cat": "入住须知", "file": "notice.html", "id": "q1", "q": "大楼前台及主要联系人", "t": "大楼前台全年全天候开放： Concierge（前台）：每天 7:00am–11:00pm Security（保安）：每天 11:00pm–7:00am Building Manager 办公室：周一至周五 9:00am–5:00pm 紧急或急需处理事项：先联系前台，由前台转交管理系统 主要联系人 Operations Manager – Pauline Tan 0456 436 159 / pauline.tan@focusedfm.com.au Building Manager 0467 888 058 / AuroraBM@focusedfm.com.au Assistant Building Manager – Ans Alvi 0448 149 772 / auroraassistantbm@focusedfm.com.au Concierge / Security 0497 777 057 / auroraconcierge@focusedfm.com.au Focused Facilities Management (03) 9329 4016 / info@focusedfm.com.au"}, {"cat": "入住须知", "file": "notice.html", "id": "q2", "q": "WeWumbo App 注册", "t": "所有住户应在 WeWumbo App 注册，用于： 核实住户身份 设施及搬家电梯预约 包裹通知 接收大楼公告 提交其他大楼服务申请 注册时需要 选择 Tenant 或 Owner 新入住选择【Moving In】；现有住户选择【Existing】 选择所属区域：Stratus（10–30楼）/ Cumulus（32–60楼）/ Australis（63–85楼） 上传有效照片身份证件 租客上传 Lease Agreement"}, {"cat": "入住须知", "file": "notice.html", "id": "q3", "q": "搬入及搬出流程", "t": "预约要求 必须通过 WeWumbo 预约：Move in/out Lift & Loading Dock 至少提前 8 小时 没有预约，大楼可以拒绝搬家 建议先确认电梯时段，再预约 Removalist 允许搬家时间 周一至周六：9:00am–5:30pm 周日及公共假期：不允许搬家 每次预约最长 3 小时 搬家电梯 10–60楼 Lift C 1800L × 2100W × 2600H mm 1300W × 2100H mm 63–85楼 Lift G 1400L × 2000W × 2700H mm 1100W × 2100H mm 尺寸不包括电梯保护垫，家具尺寸应预留余量。 搬家当天 搬家公司车辆由 Little La Trobe Street 进入 Loading Dock 住户和 Removalist 须先到 Concierge 登记 领取相关钥匙及搬家路线说明 完成后通知 Concierge 并归还钥匙 所有行李及包装垃圾须由住户或搬家公司带走 住户须承担 Loading Dock、电梯、电梯厅、走廊等区域的损坏维修费 如果不遵守规则，大楼可拒绝搬家，并且不承担 Removalist 取消费、等待费或其他损失。"}, {"cat": "入住须知", "file": "notice.html", "id": "q4", "q": "门禁、钥匙和对讲系统", "t": "对讲机 访客输入房号并按铃后： 住户按 Answer 接听 按【Door Release & Lift Release】可：解锁入口门约 5 秒、开放电梯权限约 180 秒 电梯只会允许访客选择住户所在楼层 钥匙及门禁 Apartment Key：进入公寓 FOB：进入大楼、电梯及设施区域 Car Park Remote：开启停车场卷帘门 注意事项 租客被锁在门外应联系中介"}, {"cat": "入住须知", "file": "notice.html", "id": "q5", "q": "快递及外卖", "t": "收件地址格式 必须写清楚： 收件人全名 手机号码 完整地址，例如：8601/228 La Trobe Street, Melbourne VIC 3000 资料不完整可能导致快递延误或丢失。 小型包裹 通常由快递员直接放入信箱 不一定有通知，住户需要定期检查信箱 租客遗失信箱钥匙应联系我们；业主可联系前台 中型包裹 由前台登记在 WeWumbo 住户通过 App 收到领取通知 必须注册 WeWumbo 才能收到通知 28 天未领取会退回寄件人 大型包裹（前台只接收符合以下限制的包裹） 不超过 15kg 不超过 550mm × 300mm × 300mm 收到短信后必须在 3 天内领取 超期会退回寄件人 超过限制的家具、电器等 前台可以协助联系住户，但住户必须立即到 Loading Dock 接收 多件大型物品可能需要预约搬家电梯 若住户无法及时领取，前台可以拒收 住户在签收时应提前通知前台；超大件仍需安排其他人代收 重要免责 包裹交给前台后发生的遗失、损坏和盗窃，大楼管理方不承担责任 建议贵重物品尽量由住户本人签收 外卖及食品 前台不代收食品、外卖或生鲜杂货 住户应查看配送进度并亲自到大堂接收 因未及时领取造成的变质或遗失，大楼不负责"}, {"cat": "入住须知", "file": "notice.html", "id": "q6", "q": "噪音限制", "t": "禁止产生住宅噪音的时段： 周一至周四 7:00am 以前、10:00pm 以后 周五 7:00am 以前、11:00pm 以后 周六及公共假期 9:00am 以前、11:00pm 以后 周日 9:00am 以前、10:00pm 以后 即使不在上述时段，持续时间或音量过大的也可能构成不合理噪音。 遇到噪音 立即联系 Concierge 或 Security 尽量记录时间、噪音类型及录音/录像 前台或保安会调查并口头警告 持续发生会升级至 Owners Corporation 处理 严重或持续噪音可报警"}, {"cat": "入住须知", "file": "notice.html", "id": "q7", "q": "禁烟及禁电子烟 / 公共区域", "t": "禁烟及禁电子烟 以下公共区域严禁吸烟或使用电子烟： 走廊 大堂及电梯厅 停车场和地下区域 消防楼梯 违规可能触发消防警报并收到 Breach Notice。 如果在公寓内煮食或吸烟： 不要打开入户门通风 应打开窗户通风 烟雾进入公共走廊可能触发大楼消防警报 公共区域 不可留下垃圾 不可摆放门垫、鞋子或个人物品 必须保持消防逃生通道畅通 公共区域插座仅供大楼维修使用 不可用于私人用电或电动车充电 违规会收到 Breach Notice"}, {"cat": "入住须知", "file": "notice.html", "id": "q8", "q": "公共设施及开放时间", "t": "住户可使用的设施取决于居住楼层： Stratus 10–30楼 8楼 Cumulus 32–60楼 8楼及61楼 Australis 63–85楼 8楼、61楼及86楼 所有需要预约的设施必须通过 WeWumbo 申请并获得批准。 主要设施 8楼：健身房、25米泳池、蒸汽房、桑拿房、瑜伽室、厨房、烧烤区 61楼：休息室、Wine Cellar、Games Lounge、会议室、餐厅、卡拉OK房 86楼：Australis Lounge、厨房、餐厅、Moonlight Cinema、健身房、瑜伽室、图书休息区 主要开放时间 健身房及瑜伽室：24 小时 泳池、蒸汽房及桑拿：6:00am–10:00pm 大部分休息室及功能房：8:00am–11:00pm 烧烤区：9:00am–11:00pm"}, {"cat": "入住须知", "file": "notice.html", "id": "q9", "q": "设施使用规则", "t": "使用规则 仅供住户及其受邀客人使用 不得售卖、预订或对外出租 预订住户必须全程在场 使用前须到 Concierge 登记并签署确认表 同一家公司每天只能预订同一房间一次 不得连续预约 每个设施每月最多预订 5 次 16 岁以下人员必须由成人陪同 使用后须清洁并处理垃圾 住户须对访客行为负责 损坏设施的费用由预约住户承担 禁止将装饰固定在墙面、门或其他表面 离开前关闭电源、燃气、空调及灯 健身房、泳池、桑拿、蒸汽房和瑜伽室未经许可不得拍照或录像 功能房禁止 过量饮酒 吸烟或电子烟 宠物 扩音音乐 玻璃及易碎物 尖锐物品 私人电器或厨房设备 泳池、蒸汽房及桑拿 泳池尺寸：25m 长、5m 宽、1.2m 深 进入泳池前须冲澡 不得跳水、奔跑或危险嬉戏 须自带毛巾 离开泳池区域前必须擦干 湿衣物和鞋袜不得带到泳池区域外 禁止裸泳 孕妇，或患有心脏、循环系统、呼吸系统、血压、糖尿病、肾脏疾患等人士，不建议使用蒸汽房或桑拿。饮酒、进食或运动后也应等待身体恢复后再使用。"}, {"cat": "入住须知", "file": "notice.html", "id": "q10", "q": "垃圾处理", "t": "手册发布时，垃圾槽暂时不能使用，目前要求： 不得将垃圾放在垃圾房、垃圾槽或楼层公共区域 普通垃圾及可回收物须丢到 B1 垃圾须扎紧并双层装袋，防止液体污染地毯 大纸箱必须压平 不得把家具、电器或大件垃圾放进普通垃圾桶 一氧化二氮气瓶/笑气瓶不得投入普通垃圾、回收桶或大件垃圾区，应联系供应商处理 不得把垃圾放在地面 可前往 B1 的电梯 Lift C：低层及中层住户 Lift G：高层住户 工作日 9:00am–6:00pm 期间，Lift C 及 G 可能因搬家预约被锁定，因此建议在【工作日 6:00pm–次日 9:00am】处理垃圾；周日及公共假期全天通常可使用。 大件垃圾 每月第一个星期六收集 应按收集日期才将物品放到 B1 指定区域 电子垃圾 放入大件垃圾区域附近的 E-waste Bin 仅限电器 不得放普通垃圾、纸箱或非电子大件物品 捐赠箱 每两周星期五放置在 Loading Dock 星期六收走 仅接受衣服和服饰 不接受家具及电器"}, {"cat": "入住检查", "file": "inspection.html", "id": "q1", "q": "房子里有一些小家具/杂物我不想要，怎么办？", "t": "告知你的 Property Manager 你不想要的东西，并请她发送一份【房屋原始报告】。这份报告记录了房子在出租时的状态。未经 Property Manager 书面同意，请勿移除或丢弃任何家具/物品，即使它未出现在该报告中。注意：如有家具更换/房东新添置家具等特殊情况，我们会另行告知。"}, {"cat": "入住检查", "file": "inspection.html", "id": "q2", "q": "觉得房子有点脏，房东/前租客可以报销清洁费或安排重新打扫吗？", "t": "所有房屋在交付钥匙前均已做过专业清洁 + 蒸洗地毯。可要求 Property Manager 提供清洁收据证明。 注意，每个人对清洁的标准不一样，我们已经检查完房屋并通过了我们的清洁标准。可能出现的情况：地毯不干净吸出很多灰（羊毛地毯吸出很多毛是正常的），开窗或穿鞋进入会造成藏灰/有头发，床垫有汗渍也比较难避免——特别介意可以自备床垫罩。如果有较明显的台面油渍或床垫大面积污渍，我们会安排清洁返工。"}, {"cat": "入住检查", "file": "inspection.html", "id": "q3", "q": "想换个床垫/沙发/别的家具，可以吗？", "t": "我们理解每个人对家具有自己的偏好。如果有强烈更换意愿，请先找到和现家具款式、价格【相似度高】的产品，发送给 Property Manager 征得同意。得到允许后，请自行安排丢弃（步骤同上）和安排新家具进场（记得和大楼 BM 或前台沟通预约电梯，PM 对此不负责任）。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q1", "q": "我发现有东西坏了，如何报维修？", "t": "如果是刚入住发现的，有可能是我们已知晓的问题，正在和前租客协商或等师傅排期维修/更换。如果是入住中后期发现的问题（入住 5 个工作日后），可以报告问题给 PM 并【附上照片和视频】。非紧急维修我们会在法律规定 14 天内完成，紧急维修争取两天内完成（紧急/非紧急的定义在于【是否影响最低出租标准】，包括但不限于漏水/爆炸/灶台完全不能用/马桶完全不能用/洗不了澡等，具体可网上查询）。由于澳洲人工贵，有些维修需要租客配合做初步排查，下面逐项列出可能出现的问题。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q2", "q": "怎么更改密码锁？", "t": "先用钥匙开门，在【大门打开】的情况下，按照下面的视频和文件一步步完成。初始密码为【1234#】。 电子密码设置教程 Samsung 电子锁表单"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q3", "q": "灯不亮了怎么办？", "t": "有两种情况。第一种是电路问题，我们会派电工上门检查维修，费用由房东承担。第二种是单纯灯泡不亮，属于租客使用问题——我们可以帮忙联系师傅更换，师傅最低上门费 $80+GST，如果还有别的项目一起，灯泡单算 $40+GST/个，这部分费用由租客承担。你也可以选择自己更换： 更换灯泡教程"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q4", "q": "窗户打不开 / hold 不住怎么办？", "t": "照着下图把螺丝拧紧。如果还是不行，咨询公寓前台，前台可以帮忙维修。 窗户螺丝位置示意"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q5", "q": "冰箱用不了怎么办？", "t": "有两种情况。一是冰箱一直响但不影响制冷——这种如果冰箱本身有开关电源，长按电源键即可；没有就把电闸关掉再重启。二是冰箱不制冷/不制冻——最常见原因是风道或出风口被冰堵住。大部分冰箱是单蒸发器 + 风扇循环冷气结构，冷气从蒸发器产生再通过风道吹到不同层，如果蒸发器结霜过多或风道结冰，就会不制冷。 解决方法：先让冰箱【完全断电 24–36 小时并打开门让冰完全融化】（优先拔电源线，内嵌式无法拔就把电闸关掉），时间到后擦干冰箱内部重新通电，测试是否恢复。 如果冷冻层结冰过多，可能是排水管堵塞，可以尝试清理： 冰箱排水孔清理 如果未恢复，联系 PM，我们安排维修/更换。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q6", "q": "灶台 / 电磁炉用不了怎么办？", "t": "电磁炉先检查柜子下方是否通电。灶台在排除已通电和气的前提下分两种情况：第一，开了火之后松按钮火就灭、无法持久——需要来办公室拿一张【砂纸】磨一下白色的小针即可恢复火苗。第二，转动按钮只听到“滋滋”声、只有轻微火苗——这是排气口堵住了，需要来办公室拿一个【文火针】把堵住的口通一下。以上都属于租客使用问题，平时做完饭记得及时清理灶台，不要让油渗入燃气灶，也不要用含酒精的清洁剂清洁。 灶台打不着火示意 灶台点火教程 灶台点火教程 2 燃气灶点火器不工作 如果上述尝试还是无法解决，联系 PM。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q7", "q": "烤箱灯不亮怎么办？", "t": "灯不亮不会影响使用。如果使用不了，会在租客入住前说明。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q8", "q": "洗碗机用不了怎么办？", "t": "首先检查柜子下方是否通电，屏幕上会显示错误代码。根据错误代码 + 型号 + 品牌上网搜索即可找到对应的可能性和解决方案。一般最常见的问题是出水口堵住导致不排水，需要把水管盖和滤网取下清理，同时长按开关键 15 秒重启。以上情况属于租客使用问题。 Miele 洗碗机清洁 Miele 上层托盘调整 Fisher & Paykel 清洗 Fisher & Paykel 洗碗机不下水 上层供水管道掉落 清理洗碗机 如果还是无法解决，联系 PM。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q9", "q": "洗衣机用不了怎么办？", "t": "首先检查电源是否通电/开关是否打开，屏幕上会显示错误代码，根据错误代码 + 型号 + 品牌上网搜索。建议先重启：关机、拔电源、等 5–10 分钟再插电启动，有时只是系统需要重置。不启动 → 检查门是否关紧；不脱水 → 检查是否衣物太多/集中一侧；不排水 → 检查过滤器是否堵住（机器底部小门打开即可）或排水管堵塞。以上属于租客使用问题。 洗衣房图解 洗衣机清洁维护 完全没电打不开？Troubleshooting U 管安装 洗衣机排水 / Filter 清理 洗衣机胶圈缺口 如果还是无法解决，联系 PM。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q10", "q": "烘干机用不了怎么办？", "t": "首先检查电源是否通电/开关是否打开，屏幕上会显示错误代码。建议先重启：关机、拔电源、等 5–10 分钟再插电。不启动 → 检查门是否关紧；不脱水 → 检查衣物是否太多或排水箱满了（顶部抽屉抽出即可）；不排水 → 检查滤网是否堵塞（胶圈连接处底部或侧面），取出滤网清理绒毛再试。以上属于租客使用问题。如果还是无法解决，联系 PM。 Miele 烘干机使用手册 Miele 烘干机用户手册（英文）"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q11", "q": "洗手池不下水怎么办？", "t": "一般都为头发缠/堵住了，属于租客使用问题——切记不要在水池洗头！需要买一瓶 Drano（橘色大瓶的）： 下水道堵塞处理 在水池干燥的情况下倒入半瓶，等 12 小时后用热水冲洗几分钟即可。如果还是无法解决，联系 PM。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q12", "q": "马桶漏水 / 不冲洗怎么办？", "t": "先把马桶盖打开，把水阀开关关掉，阻止进一步漏水。之后联系 PM 解决。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q13", "q": "马桶盖错位？", "t": "马桶开盖 修马桶知识点 马桶盖松了"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q14", "q": "水龙头掉落？/ 洗手盆按钮起不来怎么办？", "t": "水龙头处理 洗手盆按钮起不来"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q15", "q": "空调不工作怎么办？", "t": "如果面板出现错误代码，需要联系前台重启主机。必要时清理空调滤网： 空调滤网拆出清洗"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q16", "q": "床架掉落怎么办？", "t": "根据修复视频指导操作： 床架修复教程 如果还是不行，联系 PM。"}, {"cat": "维修问题", "file": "maintenance.html", "id": "q17", "q": "烟雾报警器 smoke alarm 不工作 / 一直在响？", "t": "可能没电，需要换电池或重置： Smoke Alarm 换电池 重置 Smoke Alarm 蜂鸣"}, {"cat": "突发情况", "file": "emergency.html", "id": "q1", "q": "钥匙丢了怎么办？", "t": "先确认丢的是 fob 门禁卡（刷电梯的圆盘）、hard key 金属钥匙（开家门的）、还是 mailbox 信箱钥匙。 如果是 fob：请拍一下手里已有的 fob 看背面有没有数字编码，然后需分两笔支付：$95 到 O Real Investment Trust（BSB 033002, Acc 037975），以及 $110 到 O REAL（BSB 733003, Acc 727393）。收到转账截图后我们即向大楼 order，一般两周内可拿。 如果是 hard key 丢了：无法重订，需赔偿 $200。 如果是 mailbox key 丢了：转账 $25.3，我们找 locksmith 订。"}, {"cat": "突发情况", "file": "emergency.html", "id": "q2", "q": "公寓停电时怎么办？", "t": "检查入户门附近的 Master Switch 是否开启 检查 Circuit Breaker 是否开启 如果跳闸，先拔掉导致问题的电器，再重新开启 如果再次跳闸：租客联系中介；业主联系电工 如果开关正常但仍无电，联系 Origin Energy 紧急热线"}, {"cat": "突发情况", "file": "emergency.html", "id": "q3", "q": "消防及紧急疏散", "t": "集合地点 火灾疏散集合点为：【State Library Victoria Forecourt】。 每层中夹层的旋转楼梯通往消防通道门，住户应遵循消防疏散指示。 低层及中层住户（10–60楼） 火警时不要寻找起火原因或抢救物品 开门前用手背检查门及门把手是否发热 经楼梯间到达消防通道 不得使用电梯 按照 Fire Warden 的指示疏散 若出口/楼梯被烟雾阻挡，拨打 Royal Call Centre 需要协助时，使用每层门内的紧急电话 未获允许不得返回大楼 高层住户（63–85楼） 火警时，高层电梯在紧急指示允许的情况下可能用于疏散 若烟雾弥漫，可通过消防楼梯前往 61 楼 Refuge Areas（避难层） 61 楼避难区域包括：Cumulus Lounge、Games Lounge、Wine Cellar 这些区域设有独立系统，可通话，消防门可供人员等候"}, {"cat": "突发情况", "file": "emergency.html", "id": "q4", "q": "防止误触警报器", "t": "不要把锅具、烤箱放置在烟感器附近，不要遮挡灭火器、消防门及喷淋头 不要遮盖烟感器 烹饪产生烟雾时，打开窗户通风，避免厨房烟雾触发警报器 住户应提前了解消防部署和紧急疏散路线 公寓内的烟雾警报器 一般位于卧室外走廊天花板 通常不连接大楼主动防火系统 闻到烟雾时会自行发出警报（通常不受消防局/物业控制） 但应尽快处理并注意 不可遮盖或拆除探测器 公共走廊声响器 公共走廊声响器连接大楼消防系统；一旦触发会自动通知消防队。因此警报响起时，绝对不要打开公寓门查看原因。"}, {"cat": "突发情况", "file": "emergency.html", "id": "q5", "q": "紧急及求助电话", "t": "警察、消防、救护车（紧急） 000 非紧急警察协助 13 14 44 Nurse on Call 1300 60 60 24 Health Direct 1800 022 222 Lifeline 心理援助支持 13 11 14 Victoria Legal Aid 1300 792 387"}, {"cat": "突发情况", "file": "emergency.html", "id": "q6", "q": "周末/公共假期紧急维修联系谁？", "t": "在周末或公共假期，联系不到 Property Manager 时，如有紧急维修情况（仅限紧急情况如漏水、漏电、钥匙忘带等），可联系以下维修人员： Handyman（杂工） Alvis 0416 971 157 Electrical（电工） Wang 0415 264 700 Plumbing（水管工） David 0430 014 680 Locksmith（锁匠） Paul 0410 974 734"}, {"cat": "合同与转租", "file": "contract.html", "id": "q1", "q": "合同快到期了，我可以续租吗？", "t": "一般房东如果没有特别安排，同时你居住状况良好、没有对房子造成损坏、保持干净整洁，都可以续一年或半年。具体安排可以咨询 PM。"}, {"cat": "合同与转租", "file": "contract.html", "id": "q2", "q": "我在租的过程中有了一个室友，需要他的名字也上合同。", "t": "可以。把你室友的基本信息发给 PM（护照 or 驾照、签证 + COE or Medicare、银行存款证明 or payslip、申请表），等待审核。审核完成后，我们会出新的合同；相关费用仅限于合理的实际成本，并以书面确认为准。"}, {"cat": "合同与转租", "file": "contract.html", "id": "q3", "q": "因不可抗力因素，我没办法继续租了，怎么办？", "t": "可转租，寻找新的人接手。转租会产生一定费用，具体合同上有注明，等确认有人接手后，转租费可以选择单独转账，或退房后从 bond 押金里扣除。 你可以自行通过网络社交媒体发布广告，也可以拜托我们用 realestate.com 和 domain 等渠道发布招租广告，广告费 $330 一次性先支付，收款账号 O REAL（BSB 733003, Acc 727393）。 请注意：交了广告费并不意味着我们保证能替你找到新租客接手。原租客须继续承担租金及相关费用，直到新租约开始或原租约以其他方式合法终止。"}, {"cat": "合同与转租", "file": "contract.html", "id": "q4", "q": "我找到新的人接手了，后面怎么操作？", "t": "请把你找到的人的基本信息发给 PM（护照 or 驾照、签证 + COE or Medicare、银行存款证明 or payslip、申请表），等待审核。审核通过后，我们会安排新的合同，待接手的人签好合同、支付完押金和第一个月租金后，你可以支付转租费、安排退房流程。"}, {"cat": "退房", "file": "move-out.html", "id": "q1", "q": "退房流程是什么？", "t": "PM 会给你发送 vacate guide，里面有退房注意事项，以及【约退房清洁】。我们可以推荐合作的清洁公司——选完整服务可以减少来回返工。但清洁和 defect 是分开的——比如地毯被染色是洗不掉的，属于 defect，不是清洁的责任。你需要以合理清洁的状态退还房屋（考虑入住时的状况）；如根据你的租约情况需要专业清洁或地毯蒸洗，请保留收据作为凭证。 【退房清洁】完成后，搬家前记得不要断电，不然我们没办法检查房屋情况。电在 5 个工作日后可自行切断。 我们会在 5 个工作日内完成【退房检查】，并把相关房屋问题发给你。你买了的项目出问题可安排清洁免费返工；没买的项目出问题需要你重新清洁或赔偿 defect。 同时，需要你和新接手房子的人签署一份 consent form，划清房屋责任。 所有问题解决后，我们会在 10 个工作日内申请解除你扣在 RTBA 的押金。收到 RTBA 的邮件后，点进去自行填写银行卡信息，就可以等押金到账了。退房流程就全部完成了。"}];